head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS30202.xml';
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.objParam = new Object();
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {

};

/********************************************** 
 * 함수명    : fn_SelectCrdtgrdRcvInfo
 * 설명       : 신용등급수신정보 조회
 ***********************************************/
scwin.fn_SelectCrdtgrdRcvInfo = function() {
    var dsNm = 'BNS_CLS_CRDTGRD_RCV_INFO';
    var qryId = 'lds.stf.bnscls.select.listCrdtgrdRcvInfo';
    var param = '&{P}V_RCV_DD=' + $c.stf.getObjectValue(edt_RcvDd);
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명    : fn_SelectCrdtgrdRcvInfoDtl
 * 설명       : 신용등급수신정보상세 조회
 ***********************************************/
scwin.fn_SelectCrdtgrdRcvInfoDtl = function(p_curRow) {
    if (p_curRow == undefined || p_curRow == "") {
        p_curRow = dts_List.getRowPosition();
    }
    var dsNm = 'BNS_CLS_CRDTGRD_RCV_INFO_DTL';
    var qryId = 'lds.stf.bnscls.select.listCrdtgrdRcvInfoDtl';
    var param = '&{P}V_RCV_DD=' + dts_List.getCellData(p_curRow, "RCV_DD");
    param += '&{P}V_CREDIT_VALU_INST_CD=' + dts_List.getCellData(p_curRow, "CREDIT_VALU_INST_CD");
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Detail, dsNm, qryId, param);
    $c.cm.ShowWin(grd_Detail);
};


/********************************************** 
 * 함수명    : fn_Save
 * 설명       : 저장
 ***********************************************/
scwin.fn_Save = function() {
    if (!scwin.fn_CheckBefSave()) {
        return;
    }
    if (!confirm(scwin.fn_SetTrsMsg("S"))) return false;
    var url = "/bns/CreditValu.do?method=saveCreditGradRcvfInfo";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&EMP_NO=" + js_emp_no;
    //dts_DtlInfo.UseChangeInfo = "False";

    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명    : fn_CheckBefSave
 * 설명       : 저장 전 체크
 ***********************************************/
scwin.fn_CheckBefSave = function() {
    var isOK = true;
    var nInsertCnt = 0;
    for (var k = 1; k <= dts_List.getTotalRow(); k++) {
        rStat = dts_List.getRowStatus(k);
        if (rStat == TB_JOB_INSERT) {
            nInsertCnt += 1;
        }
    }
    if (nInsertCnt < 1) {
        $c.win.alert("저장할 데이터가 없다.");
        isOK = false;
    }
    return isOK;
};


/********************************************** 
 * 함수명    : fn_delete
 * 설명       : 삭제
 ***********************************************/
scwin.fn_Delete = function() {
    /*
    	TB_JOB_NORMAL = 0;
    	TB_JOB_INSERT = 1;
    	TB_JOB_UPDATE = 3;
    	TB_JOB_DELETE = 2;
    */

    if (dts_List.getTotalRow() < 0 || dts_List.getRowPosition() < 1) {
        return;
    }
    if (!confirm(scwin.fn_SetTrsMsg("D"))) return false;

    // RowStatus 변경
    scwin.fn_SetRowStatus();
    var url = "/bns/CreditValu.do?method=deleteCreditGradRcvfInfo";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    trs_Delete.Action = $c.lc.fn_encodeNSession(url);
    trs_Delete.KeyName = "toinb_dataid4";
    trs_Delete.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Delete.Post();
};


/********************************************** 
 * 함수명    : fn_SetRowStatus
 * 설명       : Dataset row의 상태를 변경한다.
 ***********************************************/
scwin.fn_SetRowStatus = function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    /*ORG SRC: dts_List.UserStatus(dts_List.RowPosition) = TB_JOB_DELETE;*/
    X = TB_JOB_DELETE;
};
scwin.fn_SetTrsMsg = function(sTrsTp) {
    var sRcvt = dts_List.getCellData(dts_List.getRowPosition(), "RCV_DD");
    var sValuInstCd = dts_List.getCellData(dts_List.getRowPosition(), "CREDIT_VALU_INST_CD");
    var msg = "수신일자 : " + sRcvt + ", 평가기관 : " + sValuInstCd + "\n\n";
    if (sTrsTp == "D") {
        msg += "위 데이터를 삭제 하시겠습니까?";
    } else if (sTrsTp == "S") {
        msg += "위 데이터를 저장 하시겠습니까?";
    }
    return msg;
};


/********************************************** 
 * 함수명    : fn_addRow
 * 설명       : 행추가
 ***********************************************/
scwin.fn_addRow = function() {
    if (dts_List.getTotalRow() >= 4) {
        return;
    }
    dts_List.insertRow();
};


/********************************************** 
 * 함수명    : fn_SelectAttach
 * 설명       : 파일첨부
 ***********************************************/
scwin.fn_SelectAttach = function() {
    file.setValue("");
    file.open();
    dts_fileList.removeAll();
    if (file.getValue() != "") {
        var vFile = file.getValue();
        var vFileNm = vFile.split("\\");
        vFileNm = vFileNm[vFileNm.length - 1];
        if (vFileNm != "") {
            dts_fileList.insertRow();
        } else {
            return;
        }
        $c.stf.setObjectValue(txb_FileName, file.getValue());
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "FILE_NM", vFileNm);
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "FILE_URL", file.getValue());
    }
};



/********************************************** 
 * 함수명    : fn_FileUpload
 * 설명       : 파일첨부
 ***********************************************/
scwin.fn_FileUpload = function() {
    if (dts_fileList.getTotalRow() == 0) {
        $c.win.alert("업로드할 파일을 선택하세요.");
        return false;
    }
    if (!confirm("선택한 파일을 업로드 하시겠습니까?")) return false;
    var url = "/bns/CreditValu.do?method=uploadCreditGradFile";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_FileUp.Action = $c.lc.fn_encodeNSession(url);
    trs_FileUp.KeyName = "toinb_dataid4";
    trs_FileUp.KeyValue = "JSP(I:pFile=dts_fileList)";
    trs_FileUp.Post();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.bns.BnsPanelToGroupBox(pnl_Item);

    //수신일 현재일자로 설정
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    $c.stf.setObjectValue(edt_RcvDd, scwin.vCurDate);

    //신용등급수신정보 조회
    scwin.fn_SelectCrdtgrdRcvInfo();

    //파일업로드 데이터셋 초기화

    //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    $c.stf.showObj(file, false);
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_Detail_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Detail);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));

    //신용등급수신정보 조회
    scwin.fn_SelectCrdtgrdRcvInfo();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert(trs_Save.ErrorMsg);
};
scwin.trs_Delete_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));

    //신용등급수신정보 조회
    scwin.fn_SelectCrdtgrdRcvInfo();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert(trs_Delete.ErrorMsg);
};
scwin.trs_FileUp_OnSuccess = function() {
    dts_fileList.removeAll();
    $c.stf.setObjectValue(txb_FileName, "");
    $c.win.alert('파일업로드 성공');
};
scwin.trs_FileUp_OnFail = function() {
    $c.win.alert(trs_FileUp.ErrorMsg);
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_Delete();
};
scwin.img_RcvDd_onclick = function() {
    popUpCalendar2(edt_RcvDd);
};
scwin.dts_List_OnRowPosChanged = function(row) {
    //신용등급수신정보상세 조회

    //fn_SelectCrdtgrdRcvInfoDtl(row);

    //fn_SelectCrdtgrdRcvInfoDtl();

};
scwin.btn_Srch_onclick = function() {
    scwin.fn_SelectCrdtgrdRcvInfo();
};
scwin.btn_AddRow_onclick = function() {
    scwin.fn_addRow();
};
scwin.btn_lineadd_onclick = function() {
    scwin.fn_SelectAttach();
};
scwin.btn_fileUpload_onclick = function() {
    scwin.fn_FileUpload();
};
